JAGS:
  model{
    for(i in 1:length(y)){
      mu[i] <- alpha + beta * x[i]
      w[i]  ~ dexp(tau)
      me[i] <- (1 - 2 * p) / (p * (1 - p)) * w[i] + mu[i]
      pe[i] <- (p * (1 - p) * tau) / (2 * w[i])
      y[i]  ~ dnorm(me[i], pe[i])
    }

