  }

Stan:

data {
  int<lower=0> N;
  real<lower=0, upper=1> p;
  vector[N] x;
  vector[N] y;
}
parameters {
  real alpha;
  real beta;
  real<lower=0.001, upper=10> sigma;
  vector[N] w;
}
transformed parameters {
  real<lower=0> tau;
  vector[N] mu;
  vector[N] me;
  vector[N] pe;

  tau <- pow(sigma, -2);
  mu  <- alpha + beta * x;
  me  <- (1 - 2 * p) / (p * (1 - p)) * w + mu;
  pe  <- (p * (1 - p) * tau) ./ (2 * w);
}
model {
  # Priors
  alpha ~ normal(0, 100);
  beta  ~ normal(0, 100);
  sigma ~ cauchy(0, 2.5);

  # Data Augmentation
  w     ~ exponential(tau);

  # The model
  y     ~ normal(me, pe);
}

