functions {
// return (A \otimes B) v where:
// A is n1 x n1, B = n2 x n2, V = n2 x n1 = reshape(v,n2,n1)
matrix kron_mvprod(matrix A, matrix B, matrix V) {
return transpose(A * transpose(B * V));
}
}

data{
  int<lower=1> I;//counties
  int<lower=1> T;//time periods
  int<lower=1> K;//genders
  int<lower=1> J;//age groups

  matrix[I,I] Cmatrix;//adjacency matrix
  matrix[I,I] Identity;//Identity matrix
  real max_rho;//upper boundary of rho,to make precision matrix p.d.
  matrix[K,K] W;//prior of SIGMA
  vector[I] lambda;//eigens of Cmatrix
  vector[I*T*K] n[J];//obsed population
  //vector[I*T*K] y[J];//obsed data
  int<lower=0> y[J,I*T*K];
  matrix[T,T] A;//temporal smoothing matrix
}
transformed data{
  int KT;
  KT <- K*T;
}
parameters{
  matrix[I,T*K] Z[J];
  matrix[I,T*K] V[J];
  matrix[K,K] SIGMA[J];
  real<lower=0> delta0;
  //real<lower=0,upper=max_rho> rho[J];
  real rho[J];
}
transformed parameters{
  matrix[I,I] B;
  matrix[K,K] sig_inv;
  matrix[K*T,K*T] first_product;
  real log_rho[J];
  vector[I*T*K] log_possion_mean[J];
  vector[I*T*K] vec_Z[J];
  vector[I*T*K] vec_V[J];
  //manually calculate the inverse of 2 by 2 matrix sig_inv as follows:
  real dinominator;
  for(j in 1:J){
    vec_Z[j] <- to_vector(Z[j]);
    vec_V[j] <- to_vector(V[j]);
    log_possion_mean[j] <- log(n[j])+vec_V[j];
    B <-  Identity - rho[j]*Cmatrix;
    dinominator <- SIGMA[j][1,1]*SIGMA[j][1,1] - SIGMA[j][1,2]^2;

    sig_inv[1,1] <- SIGMA[j][2,2]/dinominator;
    sig_inv[1,2] <- -SIGMA[j][1,2]/dinominator;//negative sign, notice
    sig_inv[2,1] <- sig_inv[1,2];
    sig_inv[2,2] <- SIGMA[j][1,1]/dinominator;

    //first product
    for(d1 in 1:K){
      for(d2 in 1:K){
        for(s1 in 1:T){
          for(s2 in 1:T){
            first_product[(d1-1)*T+s1, (d2-1)*T+s2]<- sig_inv[d1,d2]*A[s1,s2];
          }
        }

      }
    }
    log_rho[j] <- 0.5*sum(1-rho[j]*lambda)*(T-2)*K-0.5*sum(Z[j].* kron_mvprod(first_product, B, Z[j]));
  }

}

model{
  delta0 ~ inv_gamma(2.0, 0.005);
  for(j in 1:J){
    rho[j] ~ uniform(0, max_rho);
    SIGMA[j] ~ inv_wishart(2,W);
    increment_log_prob(log_rho[j]);
    vec_V[j] ~ normal(vec_Z[j], delta0);//this can be improved with std normal then transforming
    y[j] ~ poisson_log(log_possion_mean[j]);
  }
}

