> > model {
> >   real fit[N];
> >   vector[51] logsichel;
> >
> >   //logsichel <- log_sichel_prob(omega, xi, gamma);
> >   logsichel <- log_sichel_prob(omega, xi, -0.5);
> >
> >   for(i in 1:N){
> >     fit[i] <- logsichel[ y[i] + 1 ];
> >   }
> >   increment_log_prob(sum(fit));
> > }
