    tau_g2[k,1]~normal(0,10);
    tau_g3[k,1]~normal(0,10);
    tail(tau_g1[k], C-2)-head(tau_g1[k], C-2)~uniform(0,1000); //C is the number of categories, the tau_g vector is length C-1, so set a prior on the differences for each item
    tail(tau_g2[k], C-2)-head(tau_g2[k], C-2)~uniform(0,1000);
