  for (n in 1:N_G3){
    if(kk_G3[n]==1){
      y_G3[n] ~ ordered_logistic(delta*theta_g3[jj_G3[n]], tau);
    }
    else{
      y_G3[n] ~ ordered_logistic(delta_g3[kk_G3[n]-1]*theta_g3[jj_G3[n]], tau_g3[kk_G3[n]-1]);
    }
  }
}

